 * - Has no random slopes, additional grouping terms, offsets, weights, or REML; use `fit_mixed_gaussian_matrix()` for those.
 * - An intercept column is prepended unless `intercept` is false, in which case `x` is used exactly.
 * - Rows with `null` or `NAN` in `x`, `y`, or another aligned input are dropped with one warning; `missing: 'raise'` rejects them instead. `retained_rows` and `dropped_rows` give the original row positions.
 * @param array<array<int|float|null>> $x Predictor matrix: one row per observation and one numeric column per predictor; null or NAN is missing
 * @param array<int|float|null> $y Numeric response, one value per row; null or NAN is missing
 * @param bool $intercept False uses x exactly (including any caller-supplied ones).
 * @param array<int|string|null> $groups Group label per row, an integer or a string; integer 1 and string "1" are different groups
 * @param string $missing 'drop' removes rows with null or NAN in any variable the model uses and warns once; 'raise' rejects them
 * @return MixedGaussianFit A fit object, read like this array:
 * array{
 *   model: 'linear'|'iv'|'ridge'|'generalized_linear'|'mixed_gaussian'|'mixed_logistic',
 *   coefficients: list<float>,
 *   covariance: list<list<float>>,
 *   std_errors: list<float>,
 *   p_values: list<float>,
 *   conf_int: list<array{float,float}>,
 *   fitted: list<float>,
 *   residuals: list<float>,
 *   log_likelihood: float,
 *   df_residual: int,
 *   diagnostics: array{converged:bool,solver:string,warnings:list<string>,iterations?:int,evaluations?:int,gradient_max?:float,boundary?:bool,singular?:bool},
 *   n_input: int,
 *   n_observations: int,
 *   n_dropped: int,
 *   retained_rows: list<int>,
 *   dropped_rows: list<int>,
 *   z_statistics: list<float>,
 *   fixed_fitted: list<float>,
 *   marginal_residuals: list<float>,
 *   aic: float,
 *   residual_variance: float,
 *   sigma: float,
 *   method: string,
 *   converged: bool,
 *   group_labels: list<int|string>,
 *   group_sizes: list<int>,
 *   random_effects: list<float>,
 *   random_effects_cond_var: list<float>,
 *   evaluations: int,
 *   n_groups: int,
 *   random_intercept_variance: float,
 *   icc: float,
 *   boundary: bool,
 * }
 * @throws \Exception A code from 1001 to 1008 for an input or statistical error.
 */
function fit_mixed_gaussian_intercept_matrix(array $x, array $y, array $groups, string $missing = 'drop', bool $intercept = true): MixedGaussianFit {}

/**
 * Fits a Gaussian mixed model on a numeric design with explicit random terms, like `lme4::lmer()`.
 * - Fits by ML unless `reml` is true.
 * - An intercept column is prepended unless `intercept` is false, in which case `x` is used exactly.
 * - Rows with `null` or `NAN` in `x`, `y`, or another aligned input are dropped with one warning; `missing: 'raise'` rejects them instead. `retained_rows` and `dropped_rows` give the original row positions.
 * @param array<array<int|float|null>> $x Predictor matrix: one row per observation and one numeric column per predictor; null or NAN is missing
 * @param array<int|float|null> $y Numeric response, one value per row; null or NAN is missing
 * @param bool $intercept False uses x exactly (including any caller-supplied ones).
 * @param array<array{z:array<array<int|float|null>>,groups:array<int|string|null>,correlated?:bool}> $random Random terms, each an array with 'z' (n × k design), 'groups' (one label per row), and optional 'correlated' (default true; false is (x || g))
 * @param string $missing 'drop' removes rows with null or NAN in any variable the model uses and warns once; 'raise' rejects them
 * @param bool $reml true for REML, false for ML
 * @param ?array $weights Positive prior weights aligned with the rows
 * @param ?array $offset Known part of the linear predictor, aligned with the rows; null is zero
 * @param ?array $start Starting relative covariance factors, in the units of the random columns; null starts diagonal factors at one and off-diagonals at zero
 * @param int $maxEvaluations Largest number of optimizer evaluations
 * @param float $tolerance BOBYQA final trust-region radius, in (0, 0.1]
 * @param string $optimizer 'bobyqa' or 'nelder_mead'
 * @param float $objectiveTolerance Nelder–Mead stopping tolerance: the standard deviation of the simplex objective values
 * @return MixedGaussianFit A fit object, read like this array:
 * array{
 *   model: 'linear'|'iv'|'ridge'|'generalized_linear'|'mixed_gaussian'|'mixed_logistic',
 *   coefficients: list<float>,
 *   covariance: list<list<float>>,
 *   std_errors: list<float>,
 *   p_values: list<float>,
 *   conf_int: list<array{float,float}>,
 *   fitted: list<float>,
 *   residuals: list<float>,
 *   log_likelihood: float,
 *   df_residual: int,
 *   diagnostics: array{converged:bool,solver:string,warnings:list<string>,iterations?:int,evaluations?:int,gradient_max?:float,boundary?:bool,singular?:bool},
 *   n_input: int,
 *   n_observations: int,
 *   n_dropped: int,
 *   retained_rows: list<int>,
 *   dropped_rows: list<int>,
 *   z_statistics: list<float>,
 *   fixed_fitted: list<float>,
 *   marginal_residuals: list<float>,
 *   aic: float,
 *   residual_variance: float,
 *   sigma: float,
 *   method: string,
 *   converged: bool,
 *   n_parameters: int,
 *   bic: float,
 *   theta: list<float>,
 *   singular: bool,
 *   optimizer: string,
 *   optimizer_implementation: string,
 *   evaluations: int,
 *   random: list<array{covariance:list<list<float>>,effects:list<list<float>>,effects_cond_var:list<list<list<float>>>,group_labels:list<int|string>,group_sizes:list<int>}>,
 * }
 * @throws \Exception A code from 1001 to 1008 for an input or statistical error.
 */
function fit_mixed_gaussian_matrix(array $x, array $y, array $random, string $missing = 'drop', bool $reml = false, ?array $weights = NULL, ?array $offset = NULL, ?array $start = NULL, int $maxEvaluations = 20000, float $tolerance = 1.0E-7, string $optimizer = 'bobyqa', float $objectiveTolerance = 1.0E-12, bool $intercept = true): MixedGaussianFit {}

/**
