 *   z_statistics: list<float>,
 *   fixed_fitted: list<float>,
 *   linear_predictor: list<float>,
 *   aic: float,
 *   bic: float,
 *   n_parameters: int,
 *   group_labels: list<int|string>,
 *   group_sizes: list<int>,
 *   random_effects: list<float>,
 *   random_effects_cond_var: list<float>,
 *   n_groups: int,
 *   random_intercept_sd: float,
 *   random_intercept_variance: float,
 *   neg2_log_likelihood: float,
 *   quadrature_points: int,
 *   integration: string,
 *   method: string,
 *   family: string,
 *   link: string,
 *   optimizer: string,
 *   converged: bool,
 *   evaluations: int,
 *   gradient_max: float,
 *   boundary: bool,
 *   singular: bool,
 *   random: list<array{label:string,group:string,columns:list<string>}>,
 *   formula: string,
 *   response: string,
 *   columns: list<string>,
 *   terms: list<string>,
 *   assign: list<int>,
 *   intercept: bool,
 *   named: array<string,float>,
 *   predvars: array{levels:array<string,list<string>>,poly:array<string,array{alpha:list<float>,norm2:list<float>}>},
 * }
 * @throws \Exception A code from 1001 to 1008 for an input or statistical error; 1007 for an unsupported function, family, or random term.
